Lemma ro_cells_reshape : forall segs m A cs cs',
  ro_cells segs m A cs -> cells_wf cs' -> cells_bytes cs' = cells_bytes cs -> ro_cells segs m A cs'.
Proof. intros segs m A cs cs' [WF B] WF' E. split; [exact WF' | rewrite E; exact B]. Qed.

Lemma ro_cells_tail : forall segs m A c cs,
  ro_cells segs m A (c :: cs) -> ro_cells segs m (A + Z.of_nat (csize c)) cs.
Proof.
  intros segs m A c cs [[WF1 WF2] B]. cbn [cells_bytes] in B. apply bytes_at_app in B. destruct B as [_ B].
  rewrite (cbytes_length c WF1) in B. split; [exact WF2 | exact B].
Qed.

Lemma ro_cells_of_bytes_at : forall segs m A bs n, bytes_at segs m A bs -> length bs = n -> ro_cells segs m A [CB n bs].
Proof. intros segs m A bs n B L. split; [cbn; tauto | cbn [cells_bytes cbytes]; rewrite app_nil_r; exact B]. Qed.
